// === Tab: mySketch ===
const sketch = (p) => {
    let min_width;
    let SEED;

    let trees = [];

    p.setup = () => {
        SEED = p.random()*998244353;
        p.randomSeed(SEED);
        p.noiseSeed(SEED);

        p.createCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);

        let cell_w = min_width * 0.95 / 3
        for(let x=-1;x<=1;++x){
            for(let y=-1;y<=1;++y){
                trees.push(new Tree(
                    p.width/2 + cell_w * x, p.height/2 + cell_w * y,
                    cell_w
                )
                );
            }
        }
        // trees.push(
        //     new Tree(p.width/2, p.height/2, min_width)
        // );

        p.background(127);

    };

    p.draw = () => {
        p.noStroke();

        for(let i=0;i<trees.length;++i){
            trees[i].update();
            trees[i].display();
        }
    };

    class Tree {
        pos;
        width;
        particles;
        branch_color;
        leaf_color;

        sub_colors;
        sub_offset;
        sub_radius;

        mx_step;
        step;
        nscale;
        time;
        constructor(x, y, width){
            this.pos = p.createVector(x, y);
            this.width = width;
            this.particles = [];
            this.particles.push(
                new Particle(x, y+width/2, p.HALF_PI, width*p.random(0.05, 0.15))
            );
            this.mx_step = 500;
            this.step = width / this.mx_step;
            this.nscale = 3 / width;
            this.time = 0;

            let red = p.random(100, 200);
            let green = p.random(40, 150);
            let blue = p.min(red, green) * 0.7;

            this.branch_color = p.color(
                red, green, blue, 10
            );
            this.sub_colors = [];
            this.sub_offset = [];
            this.sub_radius = [];
            for(let i=0;i<4;++i){
                this.sub_colors.push(p.color(
                    p.random(10, 20),
                    p.random(4, 15),
                    0,
                    150
                ));
                this.sub_offset.push(p.random(-0.5, 0.5));
                this.sub_radius.push(0.05, 0.1);
            }

            red = p.random(50, 250);
            green = p.random(50, 250);
            blue = p.min(red, green) * 0.1;

            this.leaf_color = p.color(
                red, green, blue, 20
            );
        }

        update(){
            if(this.time > this.mx_step) {return;}
            for(let i=0;i<this.particles.length;++i){
                if (this.particles.length > 100){
                    this.particles[i].angle 
                    += (p.noise(this.pos.x*this.nscale, this.pos.y*this.nscale) - 0.5) * 0.05;
                }
                else{
                    this.particles[i].angle += (p.randomGaussian(0, 0.2)) * 0.05;
                }
                this.particles[i].pos.add(p.createVector(
                    this.step*p.cos(this.particles[i].angle),
                    -this.step*p.sin(this.particles[i].angle)
                ));
                this.particles[i].radius*=0.993;

                let rs = p.random();
                if(this.particles.length < 30 && rs < 0.02 ||
                    this.particles.length >= 30 && rs < 0.008 && this.particles.length < 750) {
                    let dsg = p.random() < 0.5 ? -1:1;
                    this.particles.push(
                        new Particle(
                            this.particles[i].pos.x,
                            this.particles[i].pos.y,
                            this.particles[i].angle + dsg * (p.TWO_PI/30 + p.random(p.TWO_PI/30)),
                            this.particles[i].radius
                        )
                    )
                }
            }
            this.time += 1;
        }

        display(){
            if(this.time > this.mx_step) {return;}
            for(let i=0;i<this.particles.length;++i){
                p.fill(this.branch_color);
                p.circle(this.particles[i].pos.x, this.particles[i].pos.y, this.particles[i].radius);
                for(let j=0;j<this.sub_colors.length;++j){
                    p.fill(this.sub_colors[j]);
                    p.circle(
                        this.particles[i].pos.x + this.sub_offset[j] * this.particles[i].radius,
                        this.particles[i].pos.y,
                        this.sub_radius[j] * this.particles[i].radius
                    )
                }
                if(this.time > 300 && p.random() < 0.15 ){
                    p.fill(this.leaf_color);
                    p.circle(
                        this.particles[i].pos.x, this.particles[i].pos.y,
                        p.max(0.001, p.randomGaussian(8, 3)) * this.width / 200
                    );
                }
            }
        }
    }
    class Particle {
        pos;
        angle;
        radius;
        constructor(x, y, a, r){
            this.pos = p.createVector(x, y);
            this.angle = a;
            this.radius = r;
        }
    }
};

new p5(sketch);

